 "content": "def transform(grid):
    """Overlay the two non-background panels and mark their overlap with 2."""
    h, w = len(grid), len(grid[0])
    # Locate a solid-color divider row or column, then split into equally sized panels.
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and 0 < r < h - 1:
            a, b = grid[:r], grid[r + 1:]
            if len(a) == len(b) and len(a) > 0:
                return [[2 if x != 0 and y != 0 else 0 for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1 and 0 < c < w - 1:
            a = [row[:c] for row in grid]
            b = [row[c + 1:] for row in grid]
            if all(len(x) == len(y) for x, y in zip(a, b)):
                return [[2 if x != 0 and y != 0 else 0 for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]
    raise ValueError('No centered solid divider found')
